// 实际请求永久绑定、首history裁剪、零时死亡与多行动Advance；不拿同tick或today状态补来源。
#include "resident/domains/growth/growth_recovery_receipts.hpp"
#include "resident/kernel/command_types.hpp"
#include "resident/checkpoint/completion_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool value,const char* text){++checks;if(!value)throw std::runtime_error(text);}
// 夹具只建立具名原服务/终止及实际提交外壳，行为来源完整史由另外的history测试负责。
struct Fixture {
 std::shared_ptr<CommonCatalog> catalog=std::make_shared<CommonCatalog>();CommonStore c;GrowthState growth;GrowthRecoveryState recovery;
 Fixture():c(CommonState{},catalog){c.state().identity.tick=5;c.state().identity.revision=2;c.state().next_instance_id=100;ActorRecord a;a.id="patient";c.state().actors.insert(a.id,a);c.state().request_sequences.insert(a.id,0);}
 void close(const StableId& action,const StableId& fact,const StableId& reason="cancelled") {GrowthRecoveryService service{"patient","provider","inn","place",GrowthRecoveryMethod::safe_lodging,reason=="completed"?4:5,1,{}};recovery.services.insert(action,service);GrowthRecoveryClosure end;end.action_id=action;end.tick=5;end.reason=reason;if(reason=="completed")end.provided_half_days=1;if(reason=="patient_dead"||reason=="provider_dead")end.cause_fact_id="military:3";recovery.closures.insert(fact,end);LifeActivityRecord life;life.view.action_id=life.view.fact_id=action;life.view.actor_id="patient";life.view.provider_actor_id="provider";life.view.phase=reason=="completed"?LifeActivityPhase::completed:LifeActivityPhase::cancelled;life.view.completed_tick=5;growth.life_activities.insert(action,life);c.state().facts.insert(action,{action,"life_activity","growth"});c.state().facts.insert(fact,{fact,"personal_recovery_closed","personal_injury_recovery"});}
 std::shared_ptr<CommitResult> result(const StableId& id,Integer sequence,const StableId& kind,const ReceiptDetails& details){auto r=std::make_shared<CommitResult>();r->result_id=id;r->kind=kind;r->tick=5;r->revision=c.revision();r->details=std::make_shared<const ReceiptDetails>(details);c.state().request_sequences.set("patient",sequence);c.state().results.set("patient:"+std::to_string(sequence),r);c.state().history.push_back({5,kind,"patient",id,{}});return r;}
};
}
int main(){try{
 Fixture f;const auto before=f.recovery;f.close("action:1","recovery:2");GrowthEffect effect;effect.kind="recovery_cancel";effect.action_id="action:1";auto first=f.result("result:8",1,"recovery_cancel",ReceiptDetails{effect,{}});auto added=growth_recovery_new_closure_sources(before,f.recovery);check(added.ok&&added.value==std::vector<StableId>{"recovery:2"},"only actual new closure selected");check(!validate_growth_recovery_result_bindings(f.c,f.growth,f.recovery).ok,"unbound candidate cannot publish");check(bind_growth_recovery_result_in_candidate(f.c,f.growth,f.recovery,added.value,"patient",1,*first).ok,"actual allocated request binds once");check(validate_growth_recovery_cancel_receipt(f.c,f.growth,f.recovery,"patient",5,effect,"result:8").ok,"exact first cancel source");check(!bind_growth_recovery_result_in_candidate(f.c,f.growth,f.recovery,added.value,"patient",1,*first).ok,"same closure cannot bind twice");
 f.c.state().history.clear();auto later=f.result("result:30",2,"recovery_cancel",ReceiptDetails{effect,{}});check(!validate_growth_recovery_cancel_receipt(f.c,f.growth,f.recovery,"patient",5,effect,"result:30").ok,"trimmed first history cannot relabel sole earlier same-tick cancel");auto copy=*first;check(!read_growth_recovery_completions_for_result(f.c,f.growth,f.recovery,copy).ok,"copied result metadata is not actual cached object");check(read_growth_recovery_completions_for_result(f.c,f.growth,f.recovery,*first).ok,"original cached result retains exact source");auto old=f.recovery;f.recovery.closures.find("recovery:2")->commit_result_id="result:30";check(!growth_recovery_new_closure_sources(old,f.recovery).ok,"old permanent binding cannot be rewritten in next candidate");f.recovery=old;f.c.state().results={};f.c.state().history.clear();check(validate_growth_recovery_result_bindings(f.c,f.growth,f.recovery).ok,"normal cache/history trimming preserves permanent binding");
 Fixture late;const auto late_before=late.recovery;late.close("action:1","recovery:5");auto bad_result=late.result("result:4",1,"recovery_cancel",ReceiptDetails{effect,{}});auto late_ids=growth_recovery_new_closure_sources(late_before,late.recovery);check(late_ids.ok&&!bind_growth_recovery_result_in_candidate(late.c,late.growth,late.recovery,late_ids.value,"patient",1,*bad_result).ok,"late invalid actual result ordering rejects binding");check(late.recovery.closures.find("recovery:5")->commit_result_id.empty()&&late.recovery.closures.find("recovery:5")->commit_request_seq==0,"late binding failure restores all proposed permanent fields");
 Fixture death;const auto death_before=death.recovery;death.close("action:1","recovery:5","provider_dead");auto actual=death.result("result:9",1,"naval_round",ReceiptDetails{Done{}, {}});auto ids=growth_recovery_new_closure_sources(death_before,death.recovery);check(ids.ok&&bind_growth_recovery_result_in_candidate(death.c,death.growth,death.recovery,ids.value,"patient",1,*actual).ok,"zero-time real provider death binds actual command result");auto ended=read_growth_recovery_completions_for_result(death.c,death.growth,death.recovery,*actual);check(ended.ok&&ended.value.size()==1&&ended.value[0].action_id=="action:1"&&ended.value[0].code=="RecoveryProviderDied","zero-time Plan receives exact failed original action");
 Fixture step;const auto step_before=step.recovery;step.close("action:1","recovery:2","completed");step.close("action:4","recovery:5","patient_dead");AdvanceDetails advance;for(const auto& id:step.recovery.closures.order()){auto source=read_growth_recovery_completion(step.c,step.growth,step.recovery,id);check(source.ok,"original completion source readable");ActionCompletion done;if(!source.value.success)done.completed=true;done.success=source.value.success;if(!source.value.code.empty())done.code=source.value.code;if(source.value.success){GrowthEffect e;e.kind="service";done.growth=e;}auto json=encode_action_completion(done);check(json.ok,"original completion encoder accepts shape");auto cold=decode_action_completion(json.value);check(cold.ok&&validate_growth_recovery_action_completion(source.value,*cold.value).ok,"actual completion JSON preserves source-matched success or death code");advance.completed_actions.insert(source.value.action_id,done);}auto tick=step.result("result:9",1,"advance",ReceiptDetails{advance,{}});ids=growth_recovery_new_closure_sources(step_before,step.recovery);check(ids.ok&&bind_growth_recovery_result_in_candidate(step.c,step.growth,step.recovery,ids.value,"patient",1,*tick).ok,"same Advance binds multiple exact completions");check(read_growth_recovery_completions_for_result(step.c,step.growth,step.recovery,*tick).value.size()==2,"multiple completions retained without latest-only filter");check(step.c.state().next_instance_id==100,"binding allocates no extra common identity or money");
 std::cout<<"GROWTH_RECOVERY_RECEIPTS "<<checks<<" checks 0 failures\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
